  function batchStatic(root){root.updateMatrixWorld(true);const groups=new Map();root.traverse(o=>{if(o.isMesh&&o.children.length===0&&!o.material.transparent){const key=o.geometry.uuid+':'+o.material.uuid;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(o);}});for(const list of groups.values()){if(list.length<3)continue;const first=list[0],batch=new T.InstancedMesh(first.geometry,first.material,list.length);batch.castShadow=true;batch.receiveShadow=true;list.forEach((m,i)=>batch.setMatrixAt(i,m.matrixWorld));list.forEach(m=>m.parent.remove(m));root.add(batch);}}
